def factorial_recursive(n):
    """使用递归计算 n 的阶乘。"""
    if not isinstance(n, int) or n < 0:
        raise ValueError("输入必须是非负整数。")

    # 基本情况
    if n == 0:
        return 1

    # 递归步骤
    return n * factorial_recursive(n - 1)

# 示例用法：
# print(factorial_recursive(5))  # 返回 120
# print(factorial_recursive(0))  # 返回 1

python
def factorial_recursive(n):
    """
    使用递归计算非负整数 n 的阶乘。
    0 的阶乘定义为 1。

    Raises:
        ValueError: 如果 n 是负数。
    """
    if n < 0:
        raise ValueError("负数没有定义阶乘。")
    elif n == 0:
        return 1
    else:
        return n * factorial_recursive(n - 1)

# 示例用法:
# print(factorial_recursive(5)) # 输出: 120

